//! Full wire vectors generated by an independent ISO CAN FD implementation.
//! Provenance and reproduction: fixtures/canfd_iso_wire_vectors.md.
use dir_simulator::runtime::canfd::codec::{self, Frame, RatePhase};
use serde::Deserialize;

#[derive(Deserialize)]
struct Vector {
    id: u32,
    extended: bool,
    brs: bool,
    esi: bool,
    data: Vec<u8>,
    crc: u32,
    stuff_count: usize,
    nominal_bits: u64,
    data_bits: u64,
    bits: String,
}

fn vectors() -> Vec<Vector> {
    serde_json::from_str(include_str!("fixtures/canfd_iso_wire_vectors.json")).unwrap()
}
fn frame(v: &Vector) -> Frame {
    Frame {
        id: v.id,
        extended: v.extended,
        brs: v.brs,
        esi: v.esi,
        data: v.data.clone(),
    }
}

#[test]
fn matches_independent_iso_vectors_for_every_dlc_and_format() {
    let vectors = vectors();
    assert_eq!(vectors.len(), 128);
    for v in vectors {
        let wire = codec::encode(&frame(&v)).unwrap();
        let captured: Vec<_> = v.bits.bytes().map(|b| b - b'0').collect();
        assert_eq!(wire.crc, v.crc, "CRC id={} length={}", v.id, v.data.len());
        assert_eq!(wire.dynamic_stuff_positions.len(), v.stuff_count);
        assert_eq!(wire.phase_bits(), (v.nominal_bits, v.data_bits));
        assert_eq!(
            wire.frame,
            captured,
            "wire id={} length={}",
            v.id,
            v.data.len()
        );
        assert_eq!(
            wire.fixed_stuff_positions.len(),
            if v.data.len() <= 16 { 6 } else { 7 }
        );
        assert_eq!(wire.crc_width, if v.data.len() <= 16 { 17 } else { 21 });
        codec::verify(&frame(&v), &captured).unwrap();
        assert_eq!(codec::decode(&captured).unwrap(), frame(&v));
    }
}

#[test]
fn rejects_every_single_bit_corruption_in_independent_frames() {
    // CRC17/CRC21, base/extended, every payload length, zero/all-one/alternating/mixed.
    for v in vectors() {
        let input = frame(&v);
        let mut captured: Vec<_> = v.bits.bytes().map(|b| b - b'0').collect();
        for index in 0..captured.len() {
            captured[index] ^= 1;
            assert!(codec::verify(&input, &captured).is_err(), "bit {index}");
            assert!(
                codec::decode(&captured).is_err(),
                "decode accepted bit {index}"
            );
            captured[index] ^= 1;
        }
        captured.pop();
        assert!(codec::verify(&input, &captured).is_err());
        assert!(codec::decode(&captured).is_err());
        let mut captured: Vec<_> = v.bits.bytes().map(|b| b - b'0').collect();
        captured.push(1);
        assert!(codec::decode(&captured).is_err());
        captured.pop();
        captured[0] = 2;
        assert!(codec::decode(&captured).is_err());
    }
}

#[test]
fn accepts_only_legal_identifiers_and_dlc_lengths() {
    let mut input = Frame {
        id: 0x7ff,
        extended: false,
        brs: true,
        esi: false,
        data: vec![],
    };
    assert!(codec::encode(&input).is_ok());
    input.id += 1;
    assert!(codec::encode(&input).is_err());
    input.extended = true;
    input.id = 0x1fffffff;
    assert!(codec::encode(&input).is_ok());
    input.id += 1;
    assert!(codec::encode(&input).is_err());
    input.id = 0;
    for len in 0..=65 {
        input.data = vec![0; len];
        assert_eq!(
            codec::encode(&input).is_ok(),
            codec::DATA_LENGTHS.contains(&len)
        );
    }
}

#[test]
fn phase_boundaries_preserve_the_two_sample_point_switches() {
    for v in vectors() {
        let wire = codec::encode(&frame(&v)).unwrap();
        let (nominal, data) = wire.phase_bits();
        assert_eq!(nominal + data, wire.frame.len() as u64);
        if v.brs {
            assert_eq!(
                wire.rate_phase(wire.brs_index - 1),
                Some(RatePhase::Nominal)
            );
            assert_eq!(wire.rate_phase(wire.brs_index), Some(RatePhase::Brs));
            assert_eq!(wire.rate_phase(wire.brs_index + 1), Some(RatePhase::Data));
            assert_eq!(
                wire.rate_phase(wire.crc_delimiter_index - 1),
                Some(RatePhase::Data)
            );
            assert_eq!(
                wire.rate_phase(wire.crc_delimiter_index),
                Some(RatePhase::CrcDelimiter)
            );
            assert_eq!(
                wire.rate_phase(wire.crc_delimiter_index + 1),
                Some(RatePhase::Nominal)
            );
            // Independently sum split-bit durations for different sample points.
            // Units are 1/100th of a ps, at nominal 500 kbit/s and data 2 Mbit/s.
            let before_brs = wire.brs_index as u64 * 200_000_000;
            let brs = 80 * 2_000_000 + 30 * 500_000;
            let middle = (wire.crc_delimiter_index - wire.brs_index - 1) as u64 * 50_000_000;
            let crc_delimiter = 70 * 500_000 + 20 * 2_000_000;
            let footer = 9 * 200_000_000;
            assert_eq!(
                wire.duration_ps(500_000, 2_000_000).unwrap(),
                (before_brs + brs + middle + crc_delimiter + footer) / 100
            );
        } else {
            assert_eq!(data, 0);
            assert!((0..wire.frame.len()).all(|i| wire.rate_phase(i) == Some(RatePhase::Nominal)));
        }
        assert_eq!(wire.rate_phase(wire.frame.len()), None);
        assert!(wire.duration_ps(0, 1).is_err());
        assert!(wire.duration_ps(1, 0).is_err());
        // Unequal non-divisor rates must round the whole rational duration once.
        let num = (nominal as u128 * 7 + data as u128 * 3) * 1_000_000_000_000;
        assert_eq!(wire.duration_ps(3, 7).unwrap() as u128, num.div_ceil(21));
    }
}

#[test]
fn crc_is_sensitive_to_payload_identifier_brs_and_esi() {
    let original = Frame {
        id: 0x123,
        extended: false,
        brs: true,
        esi: false,
        data: vec![0xa5; 16],
    };
    let crc = codec::encode(&original).unwrap().crc;
    let mut modified = original.clone();
    modified.id ^= 1;
    assert_ne!(codec::encode(&modified).unwrap().crc, crc);
    let mut modified = original.clone();
    modified.data[8] ^= 1;
    assert_ne!(codec::encode(&modified).unwrap().crc, crc);
    let mut modified = original.clone();
    modified.brs = false;
    assert_ne!(codec::encode(&modified).unwrap().crc, crc);
    let mut modified = original;
    modified.esi = true;
    assert_ne!(codec::encode(&modified).unwrap().crc, crc);
}
